"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["2057"],{59675(e){e.exports=JSON.parse('{"id":"FIN-093","slug":"generally-accepted-accounting-principles","term":"Generally Accepted Accounting Principles (GAAP)","also_known_as":["GAAP"],"difficulty":"Beginner","definition":"Generally Accepted Accounting Principles (GAAP) are the standard rules and conventions that companies follow when preparing financial statements, so that reports are consistent and comparable.","explanation":["Without common rules, each company could report its results in whatever way made it look best. GAAP sets out how transactions should be recorded and presented, such as when revenue can be counted, how assets should be valued and what must be disclosed.","The term most often refers to US GAAP, the framework used by companies in the United States and set by the Financial Accounting Standards Board. Many other countries have their own national GAAP, and most have adopted or aligned closely with International Financial Reporting Standards (IFRS).","GAAP covers topics such as revenue recognition, inventory, leases, depreciation, income taxes and financial instruments. Its rules aim to make financial statements relevant, reliable and comparable over time and between companies.","When reading financial statements, it helps to know which framework was used. US GAAP and IFRS are similar in many ways, but some differences, for example in inventory methods and certain asset values, can affect reported profits and balance sheets. Companies sometimes also report \\"non-GAAP\\" figures, which exclude certain items and should be read with care."],"note":"","total":1500,"prev":{"slug":"general-partner","term":"General Partner (GP)"},"next":{"slug":"geometric-mean","term":"Geometric Mean"}}')}}]);